using AiLabs.Rules.Config;
using AiLabs.Rules.Core;
using AiLabs.Rules.Sim;
using AiLabs.Rules.State;
using AiLabs.Rules.Systems;
using AiLabs.SimTests.Support;
using Xunit;

namespace AiLabs.SimTests;

/// <summary>Q906–Q975: batch 18 coda2 — rivals/chips (schema 31, WIP local).</summary>
public class HatchRivalsChipsCoda2LaterTests
{
    static ModelState R(Game g, int c) => new ModelState { Id = g.State.TakeId(), LineId = "mini", Capability = c, Status = ModelStatus.Released, Alignment = 500, Name = "C2" };
    static void Acq(Game g, LabState r) { r.Models.Add(R(g, 505)); r.Cash = -16_000; r.WeeksInDebt = 1; Finance.Earn(g.Me, LedgerLine.CapitalIn, 85_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); }

    [Fact] public void Q906_coda2_906() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4200, 8)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 54_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Acq(g, r); Assert.Equal(31, g.State.Schema); }
    [Fact] public void Q907_coda2_907() { var g = Game.New(seed: 1601); var r = g.Rival("openaye"); r.Models.Add(R(g, 520)); r.Cash = -16_800; Finance.Earn(g.Me, LedgerLine.CapitalIn, 70_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); g.Refused(Command.Hire(r.Id, "researcher", 1), CommandError.LabAbsorbed); }
    [Fact] public void Q908_coda2_908() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4500, 6)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 46_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Acq(g, r); SaveSchemaPretend.AssertRoundTrip(g.Sim); }
